+/** Theoretical sales use and actual consumption per item, inclusive of both UTC days. */
+export function varianceReport(store, from, to) {
+  const byItem = new Map();
+  const add = (itemId, field, qty) => {
+    const entry = byItem.get(itemId) ?? { itemId, theoretical: 0, actual: 0 };
+    entry[field] = Math.round((entry[field] + qty) * 1000) / 1000;
+    byItem.set(itemId, entry);
+  };
+  for (const sale of store.data.sales ?? []) {
+    const day = sale.soldAt.slice(0, 10);
+    if (day >= from && day <= to) for (const ingredient of sale.ingredients) add(ingredient.itemId, "theoretical", ingredient.qty);
+  }
+  for (const movement of store.data.movements) {
+    const day = dayOf(movement.at);
+    if (movement.type !== "consume" || day < from || day > to || movement.qty <= 0) continue;
+    const batch = store.data.batches.find((b) => b.id === movement.batchId);
+    if (batch) add(batch.itemId, "actual", movement.qty);
+  }
+  return [...byItem.values()].filter((entry) => entry.theoretical > 0 || entry.actual > 0)
+    .map((entry) => ({ ...entry, difference: Math.round((entry.actual - entry.theoretical) * 1000) / 1000 }))
+    .sort((a, b) => a.itemId - b.itemId);
+}
